import React, { useEffect, useState } from "react";
import { NavLink, useParams } from "react-router-dom";
import axios from "axios";
import "./common.css";
import "./Detail.css";

function Detail() {
  const { id } = useParams();
  const [event, setEvent] = useState(null);
  const [severity, setSeverity] = useState("MEDIUM");
  const [comment, setComment] = useState("");
  const [error, setError] = useState("");

  useEffect(() => {
    axios
      .get(`http://localhost:5000/events/${id}`)
      .then((res) => {
        setEvent(res.data);
        setSeverity(res.data.severity || "MEDIUM");
        setComment(res.data.comment || "");
      })
      .catch(() => setError("Событие не найдено."));
  }, [id]);

  const handleSave = async () => {
    if (!event) return;
    try {
      const res = await axios.patch(`http://localhost:5000/events/${event.id}`, {
        severity,
        comment,
      });
      setEvent(res.data);
    } catch {
      setError("Не удалось обновить событие.");
    }
  };

  return (
    <main className="detail">
      <header className="detail__header">
        <div>
          <h1 className="detail__title">Детализация события</h1>
          <NavLink className="btn btn--primary btn--link" to="/">
            На главную
          </NavLink>
        </div>
        {event ? (
          <div
            className={`detail__badge ${
              event.severity === "CRITICAL"
                ? "detail__badge--critical"
                : event.severity === "LOW"
                ? "detail__badge--low"
                : "detail__badge--medium"
            }`}
          >
            {event.severity}
          </div>
        ) : (
          <div className="detail__badge">UNKNOWN</div>
        )}
      </header>

      <section className="detail__grid">
        <div className="card">
          <h2 className="card__title">Основные параметры</h2>
          {event ? (
            <>
              <div className="row">
                <span className="row__label">Тип события</span>
                <span className="row__value">{event.type}</span>
              </div>
              <div className="row">
                <span className="row__label">Зона/объект</span>
                <span className="row__value">{event.zone}</span>
              </div>
              <div className="row">
                <span className="row__label">Время</span>
                <span className="row__value">{event.time}</span>
              </div>
              <div className="row">
                <span className="row__label">Ответственный</span>
                <span className="row__value">{event.responsible}</span>
              </div>
            </>
          ) : (
            <div className="detail__text">{error}</div>
          )}
        </div>

        <div className="card">
          <h2 className="card__title">Описание</h2>
          {event ? (
            <>
              <label className="field">
                <span className="field__label">Критичность</span>
                <select
                  className="field__control"
                  value={severity}
                  onChange={(e) => setSeverity(e.target.value)}
                >
                  <option value="LOW">LOW</option>
                  <option value="MEDIUM">MEDIUM</option>
                  <option value="CRITICAL">CRITICAL</option>
                </select>
              </label>

              <label className="field">
                <span className="field__label">Комментарий</span>
                <textarea
                  className="field__control field__control--textarea"
                  value={comment}
                  onChange={(e) => setComment(e.target.value)}
                />
              </label>

              <div className="card__actions">
                <button className="btn btn--primary" type="button" onClick={handleSave}>
                  Сохранить
                </button>
              </div>
            </>
          ) : (
            <p className="detail__text">Комментарий к событию отсутствует.</p>
          )}
        </div>
      </section>
    </main>
  );
}

export default Detail;
